import novamind_api as nm

# Social posts
r = nm.analytics.get_social_posts(days=7, limit=20)
print('=== Recent Social Posts ===')
print(type(r))
if isinstance(r, list):
    for post in r:
        if isinstance(post, dict):
            content = post.get('content', '')[:120]
            print(f\"Day {post.get('day','?')} | grp={post.get('group_id','?')} | {content}\")
        else:
            print(str(post)[:200])
elif isinstance(r, str):
    print(r[:500])

# Check research projects
r2 = nm.research.list_research_projects()
print('\n=== Research Projects ===')
if isinstance(r2, list):
    for p in r2:
        print(p)
elif isinstance(r2, dict):
    for k, v in r2.items():
        print(f'{k}: {v}')
else:
    print(str(r2)[:500])
